import{_ as s,a0 as p,w as l,s as r,ao as d,I as a,x as o,a1 as e,A as u}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const g=JSON.parse('{"title":"如何在手机上安装Ubuntu Touch 13.10 | LCTT x X-CMD","titleTemplate":false,"description":"如何在手机上安装Ubuntu Touch 13.10 | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在手机上安装Ubuntu Touch 13.10 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在手机上安装Ubuntu Touch 13.10 | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/How to Install Ubuntu Touch 13.10 on Your Phone","title":"如何在手机上安装Ubuntu Touch 13.10","tag":"201311","desc":""},"relativePath":"201311/How to Install Ubuntu Touch 13.10 on Your Phone.md","filePath":"[post].md"}'),i={name:"201311/How to Install Ubuntu Touch 13.10 on Your Phone.md"};function T(b,t,h,m,c,f){const n=p("Link");return l(),r("div",null,[t[11]||(t[11]=d(`<h1 id="如何在手机上安装ubuntu-touch-13-10" tabindex="-1">如何在手机上安装Ubuntu Touch 13.10 <a class="header-anchor" href="#如何在手机上安装ubuntu-touch-13-10" aria-label="Permalink to “如何在手机上安装Ubuntu Touch 13.10”">​</a></h1><p><strong>Ubuntu Touch 13.10是Canonical公司针对手机新推出的一款操作系统，但是相对于桌面而言，它安装到手机并不是那么容易。</strong></p><p><img src="http://i1-news.softpedia-static.com/images/news2/How-to-Install-Ubuntu-Touch-13-10-On-Your-Phone-392828-2.jpg" alt=""></p><p>Canonical提供了安装Ubuntu Touch 13.10所有必要的工具。这真是个好消息，因为手动安装操作系统可是相当麻烦的。</p><p>首先提醒，此操作系统并非任何手机都能使用。因开发原因，Canonical限制其只能使用在Nexus 4设备上（代号金枪鱼和灰鲭鲨） ，而且手机必须已被解锁。</p><p>要安装工具，你将需要在终端输入几个简单的命令：</p><pre><code>sudo add-apt-repository ppa:phablet-team/tools
sudo apt-get update
sudo apt-get install phablet-tools android-tools-adb android-tools-fastboot
</code></pre><p>用户还必须确保他们的手机已被设置成开发使用。进入“设置项/关于手机”，点击“软件版本”7次。如果你操作正确，将会收到一条提示消息。</p><p>你必须从新菜单——“开发者选项”中启用USB调试，该菜单通过前面的方法已被解锁。在手机上勾选该选项时，会出现一条消息，通知用户正在配对。同意，那么你准备得差不多了。</p><p>在开始安装前的最后一步是备份你的Android系统。同样使用adb工具。只要打开终端，输入以下命令：</p><pre><code>adb backup -apk -shared -all
</code></pre><p>如果你要重新安装原来的Android系统，打开一个终端，运行以下命令：</p><pre><code>adb restore backup.ab
</code></pre><p>最后的命令至关重要，你应该使用sudo运行，以确保正确执行该命令。打开一个终端，输入以下命令：</p><pre><code>sudo phablet-flash ubuntu-system --no-backup
</code></pre><p>运行过程中应该没有任何问题，设备将最终引导到Ubuntu Touch。不要停止终端也不要中断此过程。</p><p>以上就是你需要遵照的简单步骤，这样，在所支持的设备上运作应该没有任何问题了。</p><hr>`,18)),a("p",null,[t[1]||(t[1]=o("来源于: ",-1)),e(n,{href:"http://news.softpedia.com/news/How-to-Install-Ubuntu-Touch-13-10-On-Your-Phone-392828.shtml"},{default:u(()=>[...t[0]||(t[0]=[o("http://news.softpedia.com/news/How-to-Install-Ubuntu-Touch-13-10-On-Your-Phone-392828.shtml",-1)])]),_:1})]),a("p",null,[t[4]||(t[4]=o("译者：",-1)),e(n,{href:"https://github.com/coolpigs"},{default:u(()=>[...t[2]||(t[2]=[o("coolpigs",-1)])]),_:1}),t[5]||(t[5]=o(" 校对：",-1)),e(n,{href:"https://github.com/carolinewuyan"},{default:u(()=>[...t[3]||(t[3]=[o("Caroline",-1)])]),_:1})]),a("p",null,[t[8]||(t[8]=o("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:u(()=>[...t[6]||(t[6]=[o("LCTT",-1)])]),_:1}),t[9]||(t[9]=o(" 原创翻译，",-1)),e(n,{href:"http://linux.cn/"},{default:u(()=>[...t[7]||(t[7]=[o("Linux中国",-1)])]),_:1}),t[10]||(t[10]=o(" 荣誉推出",-1))])])}const w=s(i,[["render",T]]);export{g as __pageData,w as default};
